 * @param topLevelWidget 要移除功能的顶级窗体指针。
 */
void SAFramelessHelper::removeFrom(QWidget* topLevelWidget)
{
    d_ptr->m_widgetData.reset(nullptr);
    topLevelWidget->removeEventFilter(this);
}

